import{_ as n,c as v,h as a,a as d,b as l,d as o}from"./index-DzU0agOc.js";const p="/assets/logo-BQmSJgil.png",b={class:"page-container"},r={__name:"idiom_story",setup(m){const e=l(),c=()=>{e.back()},t=()=>{},i=()=>{};return(x,s)=>(o(),v("div",b,[a("div",{class:"nav-bar"},[a("div",{class:"back-btn",onClick:c},[...s[0]||(s[0]=[a("span",{class:"back-icon"},"←",-1)])]),s[1]||(s[1]=a("span",{class:"nav-title"},"成语故事详情",-1)),s[2]||(s[2]=a("div",{class:"nav-actions"},[a("span",{class:"icon collect-icon"},"☆"),a("span",{class:"icon share-icon"},"⇱")],-1))]),s[10]||(s[10]=d('<div class="idiom-header" data-v-ad9e8cb3><div class="idiom-name-container" data-v-ad9e8cb3><span class="idiom-name" data-v-ad9e8cb3>守株待兔</span></div><div class="idiom-pinyin-container" data-v-ad9e8cb3><span class="idiom-pinyin" data-v-ad9e8cb3>shǒu zhū dài tù</span></div><div class="tag-group" data-v-ad9e8cb3><div class="tag-item" data-v-ad9e8cb3>寓言故事</div><div class="tag-item" data-v-ad9e8cb3>成语</div><div class="tag-item" data-v-ad9e8cb3>写事作文可用</div></div></div><div class="section" data-v-ad9e8cb3><div class="section-title" data-v-ad9e8cb3><div class="title-content" data-v-ad9e8cb3><span class="title-icon" data-v-ad9e8cb3>📖</span><span class="title-text" data-v-ad9e8cb3>成语解释</span></div></div><span class="section-content" data-v-ad9e8cb3> 株：露出地面的树根。比喻不主动努力，而存万一的侥幸心理，希望得到意外的收获。也比喻死守狭隘的经验，不知变通。 </span></div><div class="section" data-v-ad9e8cb3><div class="section-title" data-v-ad9e8cb3><div class="title-content" data-v-ad9e8cb3><span class="title-icon" data-v-ad9e8cb3>📜</span><span class="title-text" data-v-ad9e8cb3>成语故事</span></div></div><span class="section-content" data-v-ad9e8cb3> 从前，宋国有个农夫。一天，他在田里干活，突然看见一只兔子飞快地跑过来，一下子撞在田边的树桩上，折断了脖子死了。 </span><span class="section-content" data-v-ad9e8cb3> 农夫很高兴，他没花一点力气就捡到了一只兔子。他想：&quot;要是每天都能捡到一只兔子，那该多好啊！&quot; </span><span class="section-content" data-v-ad9e8cb3> 从那以后，农夫再也不肯下田干活了。他天天守在树桩旁边，等着再有兔子撞过来。可是，日子一天一天过去了，再也没有兔子撞在树桩上。 </span><span class="section-content" data-v-ad9e8cb3> 而他的田地因为没人耕种，也渐渐荒芜了。人们都嘲笑他太傻了。 </span></div><div class="section" data-v-ad9e8cb3><div class="section-title" data-v-ad9e8cb3><div class="title-content" data-v-ad9e8cb3><span class="title-icon" data-v-ad9e8cb3>🔖</span><span class="title-text" data-v-ad9e8cb3>成语出处</span></div></div><div class="quote-box" data-v-ad9e8cb3><span class="quote-content" data-v-ad9e8cb3> &quot;宋人有耕田者。田中有株，兔走触株，折颈而死。因释其耒而守株，冀复得兔。兔不可复得，而身为宋国笑。&quot; </span><span class="quote-source" data-v-ad9e8cb3>——《韩非子·五蠹》</span></div></div><div class="section" data-v-ad9e8cb3><div class="section-title" data-v-ad9e8cb3><div class="title-content" data-v-ad9e8cb3><span class="title-icon" data-v-ad9e8cb3>✏️</span><span class="title-text" data-v-ad9e8cb3>作文中使用示例</span></div></div><div class="example-item" data-v-ad9e8cb3><span class="example-title" data-v-ad9e8cb3>例1：写事作文《一次失败的考试》</span><span class="example-content" data-v-ad9e8cb3> 上次考试我侥幸考了满分，就以为不用努力也能保持好成绩，整天玩耍不学习。这次考试成绩一出来，我才明白，学习不能守株待兔，只有付出持续的努力，才能取得好成绩。 </span></div><div class="example-item" data-v-ad9e8cb3><span class="example-title" data-v-ad9e8cb3>例2：议论文《成功靠什么》</span><span class="example-content" data-v-ad9e8cb3> 成功从来不是偶然的，它需要我们脚踏实地，一步一个脚印地去奋斗。那些想通过守株待兔获得成功的人，最终只会一事无成。 </span></div></div><div class="section" data-v-ad9e8cb3><div class="section-title" data-v-ad9e8cb3><div class="title-content" data-v-ad9e8cb3><span class="title-icon" data-v-ad9e8cb3>💡</span><span class="title-text" data-v-ad9e8cb3>写作技巧提示</span></div></div><div class="tip-box" data-v-ad9e8cb3><span class="tip-title" data-v-ad9e8cb3>如何在作文中运用成语故事？</span><span class="tip-content" data-v-ad9e8cb3>1. 引用成语时，要先理解成语的意思和用法，避免用错</span><span class="tip-content" data-v-ad9e8cb3>2. 可以在议论文中用成语故事作为论据，增强说服力</span><span class="tip-content" data-v-ad9e8cb3>3. 在记叙文结尾，可以用成语总结道理，点明主题</span><span class="tip-content" data-v-ad9e8cb3>4. 使用成语后，可以简单解释一下，让读者更清楚你的想法</span></div></div><div class="section" data-v-ad9e8cb3><div class="section-title" data-v-ad9e8cb3><div class="title-content" data-v-ad9e8cb3><span class="title-icon" data-v-ad9e8cb3>🔍</span><span class="title-text" data-v-ad9e8cb3>近义词拓展</span></div></div><div class="synonym-group" data-v-ad9e8cb3><div class="synonym-item" data-v-ad9e8cb3>刻舟求剑</div><div class="synonym-item" data-v-ad9e8cb3>坐享其成</div><div class="synonym-item" data-v-ad9e8cb3>不劳而获</div><div class="synonym-item" data-v-ad9e8cb3>墨守成规</div></div></div>',7)),a("div",{class:"section"},[s[7]||(s[7]=a("div",{class:"section-title"},[a("div",{class:"title-content"},[a("span",{class:"title-icon"},"📝"),a("span",{class:"title-text"},"相关写作练习")])],-1)),a("div",{class:"exercise-item"},[s[3]||(s[3]=a("span",{class:"exercise-title"},"《由“守株待兔”想到的》",-1)),s[4]||(s[4]=a("span",{class:"exercise-desc"},"写一篇300字左右的议论文，谈谈你从这个成语故事中学到的道理",-1)),a("span",{class:"exercise-btn",onClick:t},"开始练习")]),a("div",{class:"exercise-item"},[s[5]||(s[5]=a("span",{class:"exercise-title"},"改写《守株待兔》",-1)),s[6]||(s[6]=a("span",{class:"exercise-desc"},"发挥想象，给守株待兔的故事增加新的情节，写成一篇400字左右的记叙文",-1)),a("span",{class:"exercise-btn",onClick:t},"开始练习")])]),a("div",{class:"section"},[a("div",{class:"section-title"},[s[8]||(s[8]=a("div",{class:"title-content"},[a("span",{class:"title-icon"},"👥"),a("span",{class:"title-text"},"同学优秀作品")],-1)),a("span",{class:"more-icon",onClick:i},">")]),s[9]||(s[9]=d('<div class="work-item" data-v-ad9e8cb3><span class="work-title" data-v-ad9e8cb3>《不要做守株待兔的人》</span><span class="work-content" data-v-ad9e8cb3>读了《守株待兔》这个故事，我明白了一个道理：做任何事情都不能心存侥幸，只有通过自己的努力，才能获得成功...</span><div class="work-author" data-v-ad9e8cb3><img class="author-avatar" src="'+p+'" data-v-ad9e8cb3><span class="author-info" data-v-ad9e8cb3>张强 | 五年级</span></div></div>',1))])]))}},k=n(r,[["__scopeId","data-v-ad9e8cb3"]]);export{k as default};
